export function dictFor(lang: Lang): Record<string, string> {
  const i = { en: 0, pl: 1, es: 2, ru: 3, zh: 4 }[lang];
  const out: Record<string, string> = {};
  for (const r of ROWS) { const v = r[i]; if (v && v !== r[0]) out[r[0]] = v; }
  return out;
}
